return [{
  json: {
    actionId,
    outcome: 'failure',
    error: 'No active email template resolved for this step.',
    retryable: false,
  },
}];

// Renders the template's stored subject/body against the lead's fields.
// Template bodies use plain {{lead.field}} tokens — these are DATA, not
// n8n expressions, so n8n never touches them; only this code does.
// Extend the `variables` map below if the CRM template editor grows more
// allowed tokens (keep it in sync with whatever the CRM UI documents as
// available variables for an email template).
const ctx = $('Execute Workflow Trigger').item.json;
const lead = ctx.lead;
const variables = {
  'lead.firstName': lead.firstName || '',
  'lead.lastName': lead.lastName || '',
  'lead.company': lead.company || '',
  'lead.ownerName': lead.ownerName || '',
};

function render(text) {
  if (!text) return '';
  let out = text;
  for (const [token, value] of Object.entries(variables)) {
    out = out.split(`{{${token}}}`).join(value);
  }
  return out;
}

return [{
  json: {
    to: lead.email,
    subject: render(ctx.template.subject || ''),
    html: render(ctx.template.body || ''),
  },
}];

const actionId = $('Execute Workflow Trigger').item.json.action.id;
const res = $input.first().json;
const failed = res && res.error !== undefined;

if (failed) {
  return [{
    json: {
      actionId,
      outcome: 'failure',
      error: typeof res.error === 'string' ? res.error : JSON.stringify(res.error),
      retryable: true,
    },
  }];
}

return [{
  json: {
    actionId,
    outcome: 'success',
    providerMessageId: res.id || res.messageId || undefined,
    providerResponse: res,
  },
}];
